import type {
  ItemsApiGetItemsRequest,
  MediaInfoApiGetPlaybackInfoRequest,
} from "@jellyfin/sdk/lib/generated-client";
import type { SolidQueryOptions } from "@tanstack/solid-query";
import { Effect, pipe } from "effect";
import type { Accessor } from "solid-js";
import {
  createEffectMutation,
  createEffectQuery,
  createQueryDataHelpers,
  createQueryKey,
  type ExtractQueryData,
} from "~/effect/tanstack/query";
import { safeAssign } from "~/lib/utils";
import { JellyfinCatalogueService } from "./service";
import type { Library, MediaItem, PlaybackMetadata } from "./types";

const LIBRARIES_TIMEOUT = "10 seconds";

type ItemQueryOptions = Accessor<
  Omit<
    SolidQueryOptions<
      MediaItem,
      unknown,
      MediaItem,
      ReturnType<typeof JellyfinCatalogueOperations.itemQueryKey>
    >,
    "queryFn" | "queryKey"
  >
>;

type PlaybackMetadataQueryOptions = Accessor<
  Omit<
    SolidQueryOptions<
      PlaybackMetadata,
      unknown,
      PlaybackMetadata,
      ReturnType<typeof JellyfinCatalogueOperations.playbackMetadataQueryKey>
    >,
    "queryFn" | "queryKey"
  >
>;

class JellyfinCatalogue {
  librariesQueryKey = createQueryKey("catalogueLibraries");
  librariesQueryDataHelpers = createQueryDataHelpers<Library[]>(
    this.librariesQueryKey
  );
  getLibraries = () =>
    createEffectQuery(() => ({
      queryKey: this.librariesQueryKey(),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.libraries()),
          Effect.timeout(LIBRARIES_TIMEOUT)
        ),
    }));

  resumeRailQueryKey = createQueryKey("catalogueResumeRail");
  resumeRailQueryDataHelpers = createQueryDataHelpers<MediaItem[]>(
    this.resumeRailQueryKey
  );
  getResumeRail = () =>
    createEffectQuery(() => ({
      queryKey: this.resumeRailQueryKey(),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.resumeRail())
        ),
    }));

  nextUpRailQueryKey = createQueryKey("catalogueNextUpRail");
  nextUpRailQueryDataHelpers = createQueryDataHelpers<MediaItem[]>(
    this.nextUpRailQueryKey
  );
  getNextUpRail = () =>
    createEffectQuery(() => ({
      queryKey: this.nextUpRailQueryKey(),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.nextUpRail({ limit: 4 }))
        ),
    }));

  latestMoviesQueryKey = createQueryKey<
    "catalogueLatestMovies",
    { search: string }
  >("catalogueLatestMovies");
  latestMoviesQueryDataHelpers = createQueryDataHelpers<
    MediaItem[],
    { search: string }
  >(this.latestMoviesQueryKey);
  getLatestMovies = (searchTerm: () => string, libraries?: Library[]) =>
    createEffectQuery(() => {
      const search = searchTerm();
      const movieLibraryId = libraries?.find(
        (library) => library.collectionType === "movies"
      )?.id;

      return {
        queryKey: this.latestMoviesQueryKey({ search }),
        queryFn: () =>
          JellyfinCatalogueService.pipe(
            Effect.flatMap((catalogue) =>
              search
                ? catalogue.items({
                    parentId: movieLibraryId,
                    enableImages: true,
                    fields: ["ParentId"],
                    includeItemTypes: ["Movie"],
                    limit: 7,
                    recursive: true,
                    searchTerm: search,
                  })
                : catalogue.latestMovieRail({ limit: 7 })
            )
          ),
        enabled: libraries?.some(
          (library) => library.collectionType === "movies"
        ),
      };
    });

  latestTVShowsQueryKey = createQueryKey<
    "catalogueLatestTVShows",
    { search: string }
  >("catalogueLatestTVShows");
  latestTVShowsQueryDataHelpers = createQueryDataHelpers<
    MediaItem[],
    { search: string }
  >(this.latestTVShowsQueryKey);
  getLatestTVShows = (searchTerm: () => string, libraries?: Library[]) =>
    createEffectQuery(() => {
      const search = searchTerm();
      const tvLibraryId = libraries?.find(
        (library) => library.collectionType === "tvshows"
      )?.id;

      return {
        queryKey: this.latestTVShowsQueryKey({ search }),
        queryFn: () =>
          JellyfinCatalogueService.pipe(
            Effect.flatMap((catalogue) =>
              search
                ? catalogue.items({
                    parentId: tvLibraryId,
                    enableImages: true,
                    fields: ["ParentId"],
                    includeItemTypes: ["Series"],
                    limit: 7,
                    recursive: true,
                    searchTerm: search,
                  })
                : catalogue.latestTvRail({ limit: 7 })
            )
          ),
        enabled: libraries?.some(
          (library) => library.collectionType === "tvshows"
        ),
      };
    });

  itemQueryKey = createQueryKey<"catalogueItem", { id: string }>(
    "catalogueItem"
  );
  itemQueryDataHelpers = createQueryDataHelpers<
    ExtractQueryData<ReturnType<typeof this.getItem>>,
    { id: string }
  >(this.itemQueryKey);
  getItem = (
    id: () => string,
    params?: ItemsApiGetItemsRequest,
    queryOptions?: ItemQueryOptions
  ) =>
    createEffectQuery(() => ({
      queryKey: this.itemQueryKey({ id: id() }),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) =>
            catalogue.itemById(id(), { enableImages: true, ...params })
          )
        ),
      ...(queryOptions ? queryOptions() : {}),
    }));

  itemsQueryKey = createQueryKey<
    "catalogueItems",
    { parentId?: string; ids?: string[]; searchTerm?: string }
  >("catalogueItems");
  itemsQueryDataHelpers = createQueryDataHelpers<
    MediaItem[],
    { parentId?: string; ids?: string[]; searchTerm?: string }
  >(this.itemsQueryKey);
  getItems = (
    params?:
      | ItemsApiGetItemsRequest
      | Accessor<ItemsApiGetItemsRequest | undefined>
  ) =>
    createEffectQuery(() => {
      const request = typeof params === "function" ? params() : params;

      return {
        queryKey: this.itemsQueryKey({
          parentId: request?.parentId,
          ids: request?.ids,
          searchTerm: request?.searchTerm,
        }),
        queryFn: () =>
          JellyfinCatalogueService.pipe(
            Effect.flatMap((catalogue) =>
              catalogue.items({ enableImages: true, ...request })
            )
          ),
      };
    });

  getNextEpisode = (item: () => MediaItem | undefined) =>
    createEffectQuery(() => ({
      queryKey: ["catalogueNextEpisode", { id: item()?.id }] as const,
      queryFn: () =>
        pipe(
          Effect.fromNullable(item()),
          Effect.flatMap((mediaItem) =>
            JellyfinCatalogueService.pipe(
              Effect.flatMap((catalogue) => catalogue.nextEpisode(mediaItem))
            )
          )
        ),
      enabled: () => Boolean(item()?.id),
    }));

  playbackMetadataQueryKey = createQueryKey<
    "cataloguePlaybackMetadata",
    { id: string }
  >("cataloguePlaybackMetadata");
  playbackMetadataDataHelpers = createQueryDataHelpers<
    PlaybackMetadata,
    { id: string }
  >(this.playbackMetadataQueryKey);
  getPlaybackMetadata = (
    id: () => string,
    params?: MediaInfoApiGetPlaybackInfoRequest,
    queryOptions?: PlaybackMetadataQueryOptions
  ) =>
    createEffectQuery(() => ({
      queryKey: this.playbackMetadataQueryKey({ id: id() }),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.playbackMetadata(id(), params))
        ),
      ...(queryOptions ? queryOptions() : {}),
    }));

  markItemPlayed = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemPlayed"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", { played: true });
            });

            yield* service.markItemPlayed(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));

  markItemUnPlayed = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemUnPlayed"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", {
                played: false,
                playbackPositionTicks: 0,
              });
            });

            yield* service.markItemUnPlayed(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));

  markItemFavorite = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemFavorite"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", { favorite: true });
            });

            yield* service.markItemFavorite(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));

  markItemUnFavorite = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemUnFavorite"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", { favorite: false });
            });

            yield* service.markItemUnFavorite(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));
}

export type JellyfinCatalogueOperationsType = JellyfinCatalogue;

export const JellyfinCatalogueOperations = new JellyfinCatalogue();

import type {
  ItemsApiGetItemsRequest,
  ItemsApiGetResumeItemsRequest,
  MediaInfoApiGetPlaybackInfoRequest,
  UserLibraryApiGetLatestMediaRequest,
} from "@jellyfin/sdk/lib/generated-client";
import { Effect } from "effect";
import { HttpError, NoEpisodeFound } from "../../../error";
import { JellyfinService, JellyfinServiceLayer } from "../service";
import { mapLibrary, mapMediaItem, mapTrackSummary } from "./mapper";
import type { Library, MediaItem, PlaybackMetadata, PlaybackSource, PlaybackStream } from "./types";

const isNotFound = (error: unknown) =>
  error instanceof HttpError && error.status === 404;

const emptyOnNotFound = <A, E, R>(effect: Effect.Effect<A[], E, R>) =>
  effect.pipe(
    Effect.catchIf(isNotFound, () => Effect.succeed([] as A[])),
  );

const asRecord = (value: unknown): Record<string, unknown> =>
  value && typeof value === "object" ? (value as Record<string, unknown>) : {};

const asArray = (value: unknown): unknown[] => (Array.isArray(value) ? value : []);

const mapPlaybackStream = (stream: unknown): PlaybackStream => {
  const record = asRecord(stream);
  return {
    index: record.Index as number | undefined,
    type: record.Type as string | undefined,
    codec: record.Codec as string | undefined,
    language: record.Language as string | undefined,
    title: record.Title as string | undefined,
    displayTitle: record.DisplayTitle as string | undefined,
    isExternal: record.IsExternal as boolean | undefined,
    deliveryUrl: record.DeliveryUrl as string | undefined,
  };
};

const mapPlaybackSource = (source: unknown): PlaybackSource => {
  const record = asRecord(source);
  return {
    id: record.Id as string | undefined,
    liveStreamId: record.LiveStreamId as string | undefined,
    path: record.Path as string | undefined,
    container: record.Container as string | undefined,
    bitrate: record.Bitrate as number | undefined,
    runtimeTicks: record.RunTimeTicks as number | undefined,
    streams: asArray(record.MediaStreams).map(mapPlaybackStream),
  };
};

const mapPlaybackMetadata = (itemId: string, playbackInfo: unknown): PlaybackMetadata => {
  const record = asRecord(playbackInfo);
  const sources = asArray(record.MediaSources);
  const streams = sources.flatMap((source) => asArray(asRecord(source).MediaStreams));

  return {
    itemId,
    sources: sources.map(mapPlaybackSource),
    chapters: asArray(record.Chapters).map((chapter) => {
      const chapterRecord = asRecord(chapter);
      return {
        name: chapterRecord.Name as string | undefined,
        startPositionTicks: chapterRecord.StartPositionTicks as number | undefined,
      };
    }),
    trackSummary: mapTrackSummary({ MediaStreams: streams } as never),
  };
};

export class JellyfinCatalogueService extends Effect.Service<JellyfinCatalogueService>()(
  "JellyfinCatalogueService",
  {
    dependencies: [JellyfinServiceLayer],
    effect: Effect.gen(function* () {
      const jellyfin = yield* JellyfinService;

      const libraries = (): Effect.Effect<Library[], unknown> =>
        emptyOnNotFound(
          jellyfin.getLibraries().pipe(
            Effect.map((items) => items.map((item) => mapLibrary(item))),
          ),
        );

      const itemById = (id: string, params?: ItemsApiGetItemsRequest) =>
        jellyfin.getItem(id, params).pipe(Effect.map((item) => mapMediaItem(item)));

      const items = (params?: ItemsApiGetItemsRequest): Effect.Effect<MediaItem[], unknown> =>
        emptyOnNotFound(
          jellyfin.getItems(params).pipe(
            Effect.map((results) => results.map((item) => mapMediaItem(item))),
          ),
        );

      const resumeRail = (params?: ItemsApiGetResumeItemsRequest): Effect.Effect<MediaItem[], unknown> =>
        emptyOnNotFound(
          jellyfin.getResumeItems(params).pipe(
            Effect.map((results) => results.map((item) => mapMediaItem(item))),
          ),
        );

      const nextUpRail = (params?: ItemsApiGetResumeItemsRequest): Effect.Effect<MediaItem[], unknown> =>
        emptyOnNotFound(
          jellyfin.getNextupItems(params).pipe(
            Effect.map((results) => results.map((item) => mapMediaItem(item))),
          ),
        );

      const latestMovieRail = (params?: UserLibraryApiGetLatestMediaRequest): Effect.Effect<MediaItem[], unknown> =>
        emptyOnNotFound(
          jellyfin.getLatestMedia({ includeItemTypes: ["Movie"], ...params }).pipe(
            Effect.map((results) => results.map((item) => mapMediaItem(item))),
          ),
        );

      const latestTvRail = (params?: UserLibraryApiGetLatestMediaRequest): Effect.Effect<MediaItem[], unknown> =>
        emptyOnNotFound(
          jellyfin.getLatestMedia({ includeItemTypes: ["Series", "Episode"], ...params }).pipe(
            Effect.map((results) => results.map((item) => mapMediaItem(item))),
          ),
        );

      const nextEpisode = (item: MediaItem) =>
        Effect.gen(function* () {
          if (!item.indexNumber) {
            return yield* new NoEpisodeFound();
          }

          const episodes = yield* items({
            parentId: item.parentId,
            fields: ["ParentId", "MediaStreams"],
            enableUserData: true,
            includeItemTypes: ["Episode"],
            sortBy: ["IndexNumber"],
            sortOrder: ["Ascending"],
            enableImages: true,
          });

          const next = episodes.reduce<MediaItem | undefined>((best, candidate) => {
            if (typeof candidate.indexNumber !== "number" || candidate.indexNumber <= item.indexNumber!) {
              return best;
            }
            if (!best || typeof best.indexNumber !== "number" || candidate.indexNumber < best.indexNumber) {
              return candidate;
            }
            return best;
          }, undefined);

          if (!next) {
            return yield* new NoEpisodeFound();
          }

          return next;
        });

      const playbackMetadata = (id: string, params?: MediaInfoApiGetPlaybackInfoRequest) =>
        jellyfin.getPlaybackState(id, params).pipe(
          Effect.map((playbackInfo) => mapPlaybackMetadata(id, playbackInfo)),
        );

      return {
        libraries,
        itemById,
        items,
        resumeRail,
        nextUpRail,
        latestMovieRail,
        latestTvRail,
        nextEpisode,
        playbackMetadata,
        markItemPlayed: jellyfin.markItemPlayed,
        markItemUnPlayed: jellyfin.markItemUnPlayed,
        markItemFavorite: jellyfin.markItemFavorite,
        markItemUnFavorite: jellyfin.markItemUnFavorite,
      };
    }),
  },
) {}

export const JellyfinCatalogueServiceLayer = JellyfinCatalogueService.Default;

import type { Api } from "@jellyfin/sdk";
import type {
  ImageType,
  ItemFields,
  ItemsApiGetItemsRequest,
  ItemsApiGetResumeItemsRequest,
  MediaInfoApiGetPlaybackInfoRequest,
  TvShowsApiGetNextUpRequest,
  UserLibraryApiGetLatestMediaRequest,
} from "@jellyfin/sdk/lib/generated-client";
import type { BaseItemDto } from "@jellyfin/sdk/lib/generated-client/models/base-item-dto";
import type { ImageRequestParameters } from "@jellyfin/sdk/lib/models/api/image-request-parameters";
import { ImageUrlsApi } from "@jellyfin/sdk/lib/utils/api/image-urls-api";
import { Effect } from "effect";
import { isArray, isEmptyArray } from "effect/Array";
import { HttpError, MutationError, NoEpisodeFound } from "../../error";
import { AuthService, AuthServiceLayer } from "../auth";
import {
  getBestLogoImageUrl as getCatalogueLogoImageUrl,
  getBestPrimaryImageUrl as getCataloguePrimaryImageUrl,
} from "./catalogue/mapper";

/*
 *
 *
 *
 *  Helpers
 *
 *
 *
 */

function arrayToObjectWithDuplicates<K extends PropertyKey, V>(
  entries: readonly (readonly [K, V])[]
): Record<K, V | V[]> {
  return entries.reduce(
    (acc, [key, value]) => {
      const existing = acc[key];

      if (existing !== undefined) {
        acc[key] = Array.isArray(existing)
          ? [...existing, value]
          : [existing, value];
      } else {
        acc[key] = value;
      }

      return acc;
    },
    {} as Record<K, V | V[]>
  );
}

const getImageByKey = (jf: Api, item: BaseItemDto, keyTag: ImageType) =>
  new ImageUrlsApi(jf.configuration).getItemImageUrl(item, keyTag, {
    quality: 75,
  });

/**
 * Jellyfin-Web–style fallback chain for the best available primary image.
 * Tries, in order:
 *  1. ImageTags.Primary  (own item)
 *  2. SeriesPrimaryImageTag + SeriesId
 *  3. PrimaryImageTag    (some DTOs carry this at top-level with own Id)
 *  4. ParentPrimaryImageTag + ParentPrimaryImageItemId (inferred from ParentId)
 *  5. AlbumPrimaryImageTag + AlbumId
 *  6. BackdropImageTags  (first own backdrop)
 *  7. SeriesThumbImageTag + SeriesId
 *  8. ParentThumbImageTag + ParentThumbItemId
 *  9. ParentBackdropImageTags + ParentBackdropItemId (first parent backdrop)
 * Falls back to the tagless `/Items/{id}/Images/Primary` URL.
 */
const getBestPrimaryImageUrl = (
  api: ImageUrlsApi,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): string => {
  const id = item.Id ?? "";

  // 1. Own primary tag
  if (item.ImageTags?.Primary) {
    return api.getItemImageUrlById(id, "Primary" as ImageType, {
      ...params,
      tag: item.ImageTags.Primary,
    });
  }

  // 2. Series primary
  if (item.SeriesPrimaryImageTag && item.SeriesId) {
    return api.getItemImageUrlById(item.SeriesId, "Primary" as ImageType, {
      ...params,
      tag: item.SeriesPrimaryImageTag,
    });
  }

  // 3. Top-level PrimaryImageTag (rare but present on some DTOs)
  if ((item as Record<string, unknown>).PrimaryImageTag) {
    return api.getItemImageUrlById(id, "Primary" as ImageType, {
      ...params,
      tag: (item as Record<string, unknown>).PrimaryImageTag as string,
    });
  }

  // 4. Parent primary
  const parentPrimaryId =
    (item as Record<string, unknown>).ParentPrimaryImageItemId as
      | string
      | undefined;
  const parentPrimaryTag =
    (item as Record<string, unknown>).ParentPrimaryImageTag as
      | string
      | undefined;
  if (parentPrimaryTag && parentPrimaryId) {
    return api.getItemImageUrlById(parentPrimaryId, "Primary" as ImageType, {
      ...params,
      tag: parentPrimaryTag,
    });
  }

  // 5. Album primary (music items)
  if (item.AlbumPrimaryImageTag && item.AlbumId) {
    return api.getItemImageUrlById(item.AlbumId, "Primary" as ImageType, {
      ...params,
      tag: item.AlbumPrimaryImageTag,
    });
  }

  // 6. Own backdrop (first)
  if (item.BackdropImageTags && item.BackdropImageTags.length > 0) {
    return api.getItemImageUrlById(id, "Backdrop" as ImageType, {
      ...params,
      tag: item.BackdropImageTags[0],
    });
  }

  // 7. Series thumb
  if (item.SeriesThumbImageTag && item.SeriesId) {
    return api.getItemImageUrlById(item.SeriesId, "Thumb" as ImageType, {
      ...params,
      tag: item.SeriesThumbImageTag,
    });
  }

  // 8. Parent thumb
  if (item.ParentThumbImageTag && item.ParentThumbItemId) {
    return api.getItemImageUrlById(
      item.ParentThumbItemId,
      "Thumb" as ImageType,
      { ...params, tag: item.ParentThumbImageTag },
    );
  }

  // 9. Parent backdrop (first)
  if (
    item.ParentBackdropImageTags &&
    item.ParentBackdropImageTags.length > 0 &&
    item.ParentBackdropItemId
  ) {
    return api.getItemImageUrlById(
      item.ParentBackdropItemId,
      "Backdrop" as ImageType,
      { ...params, tag: item.ParentBackdropImageTags[0] },
    );
  }

  // 10. Tagless fallback
  return api.getItemImageUrlById(id);
};

/**
 * Fallback chain for the best available Logo image URL.
 *  1. ImageTags.Logo (own item)
 *  2. ParentLogoImageTag + ParentLogoItemId
 * Returns undefined when no logo metadata is available.
 */
const getBestLogoImageUrl = (
  api: ImageUrlsApi,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): string | undefined => {
  const id = item.Id ?? "";

  // 1. Own logo tag
  if (item.ImageTags?.Logo) {
    return api.getItemImageUrlById(id, "Logo" as ImageType, {
      ...params,
      tag: item.ImageTags.Logo,
    });
  }

  // 2. Parent logo
  if (item.ParentLogoImageTag && item.ParentLogoItemId) {
    return api.getItemImageUrlById(item.ParentLogoItemId, "Logo" as ImageType, {
      ...params,
      tag: item.ParentLogoImageTag,
    });
  }

  return;
};

const getImagesFromTags = (
  tags: BaseItemDto["ImageTags"],
  jf: Api,
  item: BaseItemDto
) => {
  if (!tags) {
    return {};
  }
  const images = Object.entries(tags).map(
    ([k, _v]) => [k, getImageByKey(jf, item, k as ImageType)] as const
  );

  return arrayToObjectWithDuplicates(images);
};

export type WithImage<T> = T extends Array<infer U>
  ? Array<U & { Image: string; Images: ReturnType<typeof getImagesFromTags> }>
  : T extends undefined
    ? undefined
    : T & { Image: string; Images: ReturnType<typeof getImagesFromTags> };

export const getImages =
  (jf: Api) =>
  <T extends BaseItemDto | BaseItemDto[] | undefined>(
    items: T
  ): Effect.Effect<WithImage<T>, never, never> => {
    if (!items) {
      return Effect.succeed(undefined as WithImage<T>);
    }

    return Effect.sync(() => {
      if (isArray(items)) {
        return items.map((item) => {
          const imageTags = getImagesFromTags(
            item.ImageTags,
            // jf.basePath,
            jf,
            // item.Id as string
            item
          );

          return {
            ...item,
            Image: getCataloguePrimaryImageUrl(
              new ImageUrlsApi(jf.configuration),
              item,
            ),
            Images: Object.assign(imageTags, {
              Backdrop: new ImageUrlsApi(
                jf.configuration
              ).getItemBackdropImageUrls(item),
              ...(!imageTags.Logo && {
                Logo: getCatalogueLogoImageUrl(
                  new ImageUrlsApi(jf.configuration),
                  item,
                ),
              }),
            }),
          };
        }) as unknown as WithImage<T>;
      }

      const imageTags = getImagesFromTags(
        items.ImageTags,
        jf,
        // jf.basePath,
        // items.Id as string
        items
      );

      return {
        ...items,
        Image: getCataloguePrimaryImageUrl(
          new ImageUrlsApi(jf.configuration),
          items,
          { quality: 40 },
        ),
        Images: Object.assign(imageTags, {
          Backdrop: new ImageUrlsApi(jf.configuration).getItemBackdropImageUrls(
            items
          ),
          ...(!imageTags.Logo && {
            Logo: getCatalogueLogoImageUrl(
              new ImageUrlsApi(jf.configuration),
              items,
            ),
          }),
        }),
      } as unknown as WithImage<T>;
    });
  };

const SUPPORTED_COLLECTION_TYPES = ["movies", "tvshows"] as const;

// Helper function to filter supported libraries
const filterSupportedLibraries = (items?: BaseItemDto[]) =>
  Effect.succeed(
    items?.filter(
      (item) =>
        item.CollectionType &&
        // biome-ignore lint/suspicious/noExplicitAny: filtering
        SUPPORTED_COLLECTION_TYPES.includes(item.CollectionType as any)
    ) ?? []
  );

