/** Shared language-chip row used by episode card variants. */
function LanguageChips(props: {
  label: string;
  langs: (string | null | undefined)[];
  borderColor: string;
  bgColor: string;
  textColor: string;
  mutedBorder: string;
  mutedBg: string;
  mutedText: string;
}) {
  const visible = () => props.langs.slice(0, MAX_LANG_CHIPS);
