import type { ImageType } from "@jellyfin/sdk/lib/generated-client";
import type { BaseItemDto } from "@jellyfin/sdk/lib/generated-client/models/base-item-dto";
import type { ImageRequestParameters } from "@jellyfin/sdk/lib/models/api/image-request-parameters";
import { ImageUrlsApi } from "@jellyfin/sdk/lib/utils/api/image-urls-api";
import type { Artwork, Library, MediaItem, MediaItemType, TrackSummary } from "./types";

const unique = (values: Array<string | null | undefined>) =>
  [...new Set(values.filter((value): value is string => Boolean(value)))];

const mapMediaItemType = (type?: string): MediaItemType => {
  switch (type) {
    case "Movie":
      return "movie";
    case "Series":
      return "series";
    case "Season":
      return "season";
    case "Episode":
      return "episode";
    case "CollectionFolder":
      return "library";
    default:
      return "unknown";
  }
};

export const getBestPrimaryImageUrl = (
  api: ImageUrlsApi,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): string => {
  const id = item.Id ?? "";

  if (item.ImageTags?.Primary) {
    return api.getItemImageUrlById(id, "Primary" as ImageType, {
      ...params,
      tag: item.ImageTags.Primary,
    });
  }

  if (item.SeriesPrimaryImageTag && item.SeriesId) {
    return api.getItemImageUrlById(item.SeriesId, "Primary" as ImageType, {
      ...params,
      tag: item.SeriesPrimaryImageTag,
    });
  }

  const record = item as Record<string, unknown>;
  if (record.PrimaryImageTag) {
    return api.getItemImageUrlById(id, "Primary" as ImageType, {
      ...params,
      tag: record.PrimaryImageTag as string,
    });
  }

  const parentPrimaryId = record.ParentPrimaryImageItemId as string | undefined;
  const parentPrimaryTag = record.ParentPrimaryImageTag as string | undefined;
  if (parentPrimaryTag && parentPrimaryId) {
    return api.getItemImageUrlById(parentPrimaryId, "Primary" as ImageType, {
      ...params,
      tag: parentPrimaryTag,
    });
  }

  if (item.AlbumPrimaryImageTag && item.AlbumId) {
    return api.getItemImageUrlById(item.AlbumId, "Primary" as ImageType, {
      ...params,
      tag: item.AlbumPrimaryImageTag,
    });
  }

  if (item.BackdropImageTags && item.BackdropImageTags.length > 0) {
    return api.getItemImageUrlById(id, "Backdrop" as ImageType, {
      ...params,
      tag: item.BackdropImageTags[0],
    });
  }

  if (item.SeriesThumbImageTag && item.SeriesId) {
    return api.getItemImageUrlById(item.SeriesId, "Thumb" as ImageType, {
      ...params,
      tag: item.SeriesThumbImageTag,
    });
  }

  if (item.ParentThumbImageTag && item.ParentThumbItemId) {
    return api.getItemImageUrlById(item.ParentThumbItemId, "Thumb" as ImageType, {
      ...params,
      tag: item.ParentThumbImageTag,
    });
  }

  if (
    item.ParentBackdropImageTags &&
    item.ParentBackdropImageTags.length > 0 &&
    item.ParentBackdropItemId
  ) {
    return api.getItemImageUrlById(item.ParentBackdropItemId, "Backdrop" as ImageType, {
      ...params,
      tag: item.ParentBackdropImageTags[0],
    });
  }

  return api.getItemImageUrlById(id);
};

export const getBestLogoImageUrl = (
  api: ImageUrlsApi,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): string | undefined => {
  const id = item.Id ?? "";

  if (item.ImageTags?.Logo) {
    return api.getItemImageUrlById(id, "Logo" as ImageType, {
      ...params,
      tag: item.ImageTags.Logo,
    });
  }

  if (item.ParentLogoImageTag && item.ParentLogoItemId) {
    return api.getItemImageUrlById(item.ParentLogoItemId, "Logo" as ImageType, {
      ...params,
      tag: item.ParentLogoImageTag,
    });
  }
};

export const mapArtwork = (
  jf: Api,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): Artwork => {
  const api = new ImageUrlsApi(jf.configuration);
  return {
    primary: getBestPrimaryImageUrl(api, item, params),
    backdrop: api.getItemBackdropImageUrls(item)[0],
    logo: getBestLogoImageUrl(api, item, params),
  };
};

export const mapTrackSummary = (item: BaseItemDto): TrackSummary => {
  const streams = item.MediaStreams ?? [];
  return {
    audioLanguages: unique(
      streams.filter((stream) => stream.Type === "Audio").map((stream) => stream.Language),
    ),
    subtitleLanguages: unique(
      streams.filter((stream) => stream.Type === "Subtitle").map((stream) => stream.Language),
    ),
  };
};

const mapEnrichedArtwork = (item: BaseItemDto): Artwork => {
  const record = item as Record<string, unknown>;
  const images = record.Images as Record<string, unknown> | undefined;
  const backdrop = images?.Backdrop;

  return {
    primary: record.Image as string | undefined,
    backdrop: Array.isArray(backdrop) ? backdrop[0] : (backdrop as string | undefined),
    logo: images?.Logo as string | undefined,
  };
};

export const mapMediaItem = (item: BaseItemDto, jf?: Api): MediaItem => ({
  id: item.Id ?? "",
  name: item.Name ?? "",
  type: mapMediaItemType(item.Type),
  jellyfinType: item.Type,
  overview: item.Overview,
  year: item.ProductionYear,
  premiereDate: item.PremiereDate,
  runtimeTicks: item.RunTimeTicks,
  communityRating: item.CommunityRating,
  officialRating: item.OfficialRating,
  genres: item.Genres ?? [],
  parentId: item.ParentId,
  seriesId: item.SeriesId,
  seriesName: item.SeriesName,
  seasonName: item.SeasonName,
  indexNumber: item.IndexNumber,
  parentIndexNumber: item.ParentIndexNumber,
  childCount: item.ChildCount,
  locationType: item.LocationType,
  studios: item.Studios?.map((studio) => studio.Name).filter((name): name is string => Boolean(name)) ?? [],
  people:
    item.People?.map((person) => ({
      name: person.Name ?? "",
      role: person.Role,
      type: person.Type,
      imageUrl: person.PrimaryImageTag && person.Id && jf
        ? new ImageUrlsApi(jf.configuration).getItemImageUrlById(person.Id, "Primary" as ImageType, {
            tag: person.PrimaryImageTag,
          })
        : undefined,
    })).filter((person) => Boolean(person.name)) ?? [],
  trackSummary: mapTrackSummary(item),
  userData: {
    played: item.UserData?.Played ?? false,
    favorite: item.UserData?.IsFavorite ?? false,
    playbackPositionTicks: item.UserData?.PlaybackPositionTicks,
    playedPercentage: item.UserData?.PlayedPercentage,
    unplayedItemCount: item.UserData?.UnplayedItemCount,
  },
  artwork: jf ? mapArtwork(jf, item) : mapEnrichedArtwork(item),
});

export const mapLibrary = (item: BaseItemDto, jf?: Api): Library => ({
  id: item.Id ?? "",
  name: item.Name ?? "",
  collectionType: item.CollectionType,
  itemCount: item.ChildCount,
  artwork: jf ? mapArtwork(jf, item) : mapEnrichedArtwork(item),
});

import type { Api } from "@jellyfin/sdk";
import {
  PlayMethod,
  type PlaystateApi,
} from "@jellyfin/sdk/lib/generated-client";
import { getPlaystateApi } from "@jellyfin/sdk/lib/utils/api/playstate-api";
import type { UnlistenFn } from "@tauri-apps/api/event";
import { getAllWindows, getCurrentWindow } from "@tauri-apps/api/window";
import { Effect, pipe } from "effect";
import { createEffect, on, onCleanup } from "solid-js";
import { produce } from "solid-js/store";
import {
  DEFAULT_VIDEO_PLAYBACK,
  useVideoContext,
} from "~/contexts/video-context";
import { useRuntime } from "~/effect/runtime/use-runtime";
import { AuthService } from "~/effect/services/auth";
import { JellyfinOperations } from "~/effect/services/jellyfin/operations";
import { JellyfinService } from "~/effect/services/jellyfin/service";
import { createEffectQuery } from "~/effect/tanstack/query";
import { commands, events } from "~/lib/tauri";

export const createTauriListener = <K extends keyof typeof events>(
  event: K,
  handler: (
    payload: Parameters<Parameters<(typeof events)[K]["listen"]>[0]>[0]
  ) => void
) => {
  let unlisten: UnlistenFn | null = null;
  let isSetup = false;

  createEffect(async () => {
    if (isSetup) {
      return;
    }

    isSetup = true;
    unlisten = await events[event].listen(handler);
  });

  onCleanup(() => {
    if (unlisten) {
      unlisten();
      unlisten = null;
    }
    isSetup = false;
  });
};

// for getting percentage of current time from duration
function getPercentage(current: number, total: number): number {
  if (total === 0) {
    return 0;
  }
  return (current / total) * 100;
}

const getJellyfinStreamUrl = (jf: Api, id: string) =>
  `${jf.basePath}/Videos/${id}/Stream?api_key=${jf.accessToken}&container=mp4&static=true`;

const convertPlaybackTicksToSeconds = (tick: number) => tick / 10_000_000;

export const useVideo = (id: string) => {
  const runtime = useRuntime();

  const [state, setState] = useVideoContext();

  const jf = runtime.runSync(
    Effect.gen(function* () {
      const auth = yield* AuthService;
      const api = yield* auth.getApi();

      return { api };
    })
  );

  const item = createEffectQuery(() => ({
    queryKey: JellyfinOperations.itemQueryKey({ id }),
    queryFn: () =>
      JellyfinService.pipe(
        Effect.flatMap((jf) =>
          jf.getItem(id, {
            enableImages: true,
            enableUserData: true,
          })
        ),
        Effect.tap(() => Effect.logInfo("fetched item, now start the video")),

        Effect.tap((data) =>
          Effect.promise(async () => {
            // here we will load the video
            await events.requestFileLoad.emit({
              url: getJellyfinStreamUrl(jf.api, data.Id as string),
              start_time: convertPlaybackTicksToSeconds(
                data.UserData?.PlaybackPositionTicks ?? 0
              ),
            });

            await events.requestPlayBackState.emit({ pause: false });
          })
        )
      ),
    refetchOnWindowFocus: false,
  }));

  const playSessionId = crypto.randomUUID();

  const progressHelper = new ProgressHelper(jf.api);

  const nextItem = createEffectQuery(() => ({
    queryKey: ["getNextEpisode", { id: item?.data?.Id }],
    queryFn: () =>
      pipe(
        Effect.fromNullable(item.data),
        Effect.flatMap((i) =>
          JellyfinService.pipe(Effect.flatMap((jf) => jf.getNextEpisode(i)))
        )
      ),

    // enabled: when the user reaches last 15% of video
    enabled: () =>
      Boolean(item.data?.Id) &&
      getPercentage(state.currentTime, state.duration) > 80,
  }));

  /*
   *
   *
   *
   *
   *  Tauri Listener
   *
   *
   *
   *
   */
  createTauriListener("fileLoadedChange", async ({ payload }) => {
    setState(
      produce((state) => {
        state.duration = payload.duration;
        state.currentTime = payload.current_time;
      })
    );
    setState("duration", () => payload.duration);
    setState("currentTime", () => payload.current_time);

    await progressHelper.start(playSessionId, item.data?.Id as string);
  });

  createTauriListener("playBackStateChange", ({ payload }) => {
    // change playback state
    setState("pause", () => payload.pause);
  });

  createTauriListener("playBackTimeChange", ({ payload }) => {
    // change playback state
    const time = Number(payload.position) ?? 0;
    setState("currentTime", () => time);
  });

  createTauriListener("speedEventChange", ({ payload }) => {
    // change playback state
    setState("speed", () => Number(payload.speed) ?? 0);
  });

  createTauriListener("volumeEventChange", ({ payload }) => {
    // change playback state
    setState(
      produce((st) => {
        if (st.isMuted && payload.percentage === 0) {
          return;
        }

        if (st.isMuted) {
          st.isMuted = false;
        }

        st.volume = Number(payload.percentage) ?? 0;
      })
    );
  });

  createTauriListener("audioTrackChange", ({ payload }) => {
    setState("audioTracks", () => payload.tracks);
  });

  createTauriListener("subtitleTrackChange", ({ payload }) => {
    setState("subtitleTracks", () => payload.tracks);
  });

  createTauriListener("pauseForCacheChange", ({ payload: _ }) => {
    // for checking
  });

  createTauriListener("bufferingStateChange", ({ payload: _ }) => {
    // for bufferState
  });

  createTauriListener("cacheTimeChange", ({ payload }) => {
    // for checking
    setState("cachedTime", () => payload.time);
  });

  createTauriListener("eofEventChange", async () => {
    await progressHelper.stop(
      playSessionId,
      item.data?.Id as string,
      state.currentTime
    );
  });

  /*
   *
   *
   *
   *
   *  State Monitor
   *
   *
   *
   *
   */
  createEffect(
    on(
      () => state.pause,
      async (pause) => events.requestPlayBackState.emit({ pause }),
      { defer: true }
    )
  );

  createEffect(
    on(
      () => state.speed,
      async (speed) => await events.requestSpeedEvent.emit({ speed }),
      { defer: true }
    )
  );

  let lastProgressReportTime = 0;

  createEffect(
    on(
      () => state.currentTime,
      async (time) => {
        const now = Date.now();
        if (now - lastProgressReportTime >= 3000 && jf.api) {
          lastProgressReportTime = now;

          await progressHelper.progress(
            playSessionId,
            item.data?.Id as string,
            time
          );
        }
      },
      { defer: true }
    )
  );

  createEffect(
    on(
      () => state.isMuted,
      async (muted) => {
        if (muted) {
          await events.requestVolumeEvent.emit({ percentage: 0 });
        }
      },
      { defer: true }
    )
  );

  createEffect(
    on(
      () => state.volume,
      async (volume) => {
        if (!volume) {
          setState("isMuted", () => true);
          return;
        }

        await events.requestVolumeEvent.emit({ percentage: volume });
      },
      { defer: true }
    )
  );

  /*
   *
   *
   *
   *
   * PIP Window
   *
   *
   *
   */

  const showPipWindow = async () => {
    await commands.showPipWindow();

    setState("isPip", () => true);
  };

  const hidePipWindow = async () => {
    await commands.hidePipWindow();

    setState("isPip", () => false);
  };

  const isPipShowing = async () => {
    const windows = await getAllWindows();
    const pip_window = windows.find((win) => win.label === "pip");

    return Boolean(pip_window?.isVisible());
  };

  /*
   *
   *
   *
   * Cleanup
   *
   *
   *
   */

  onCleanup(async () => {
    const itemId = id;
    const currentTime = state.currentTime;
    // Clear State
    setState(() => DEFAULT_VIDEO_PLAYBACK());
    await progressHelper.stop(playSessionId, itemId, currentTime);
    // clean up state
    await events.requestPlayBackState.emit({ pause: true });
    await events.requestClearEvent.emit();

    // fullscreen
    const window = getCurrentWindow();
    if (await window.isFullscreen()) {
      commands.toggleFullscreen();
    }

    // commands pip window
    await commands.hidePipWindow();
  });

  return {
    state,
    setState,
    item: () => item.data,
    nextItem: () => nextItem.data,
    showPipWindow,
    hidePipWindow,
    isPipShowing,
  };
};

class ProgressHelper {
  playstate: PlaystateApi;
  constructor(api: Api) {
    this.playstate = getPlaystateApi(api);
  }

  async start(sessionId: string, currentId: string) {
    await this.playstate.reportPlaybackStart({
      playbackStartInfo: {
        ItemId: currentId,
        PlaySessionId: sessionId,
        PlayMethod: PlayMethod.DirectStream,
        CanSeek: true,
        IsPaused: false,
        VolumeLevel: 100, // Clamp to 100 for Jellyfin
      },
    });
  }

  async progress(sessionId: string, currentId: string, currentTime: number) {
    await this.playstate.reportPlaybackProgress({
      playbackProgressInfo: {
        ItemId: currentId,
        PlaySessionId: sessionId,
        PlayMethod: PlayMethod.DirectStream,
        PositionTicks: Math.floor(currentTime * 10_000_000),
        CanSeek: true,
      },
    });
  }

  async stop(sessionId: string, currentId: string, currentTime: number) {
    await this.playstate.reportPlaybackStopped({
      playbackStopInfo: {
        ItemId: currentId,
        PlaySessionId: sessionId,
        PositionTicks: Math.floor(currentTime * 10_000_000),
      },
    });
  }
}

